import json
import subprocess
from pathlib import Path

safe_ingest = "/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin/scripts/safe_ingest.py"
config_path = "/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-workspace/config.json"

def run_safe_ingest(subcmd, *args):
    cmd = ["python3", safe_ingest, "--config", config_path, subcmd] + list(args)
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        print(f"Error running {cmd}: {res.stderr}")
        return None
    try:
        return json.loads(res.stdout)
    except:
        return res.stdout

prs = run_safe_ingest("pr-list", "--repo", "matthewmcneill/esp32-app-foundation", "--state", "all", "--limit", "30")
if isinstance(prs, list):
    print(f"Total PRs fetched: {len(prs)}")
    for pr in prs[:15]:
        labels = [l["name"] for l in pr.get("labels", [])]
        print(f"PR #{pr.get('number')} ({pr.get('state')}): {pr.get('title')}")
        print(f"   Created: {pr.get('createdAt')}, Updated: {pr.get('updatedAt')}")
        print(f"   Labels: {labels}")
else:
    print("PRs output:", prs)

issues = run_safe_ingest("issue-list", "--repo", "matthewmcneill/esp32-app-foundation", "--state", "open")
if isinstance(issues, list):
    print(f"\nOpen Issues: {len(issues)}")
    for iss in issues:
        labels = [l["name"] for l in iss.get("labels", [])]
        print(f"Issue #{iss.get('number')} ({iss.get('state')}): {iss.get('title')}")
        print(f"   Labels: {labels}")

