import json
from pathlib import Path

p = Path("/Users/mcneillm/.gemini/antigravity/brain/e5f1d59b-75d1-433d-810a-600350e86169/.system_generated/logs/transcript.jsonl")
test_calls = []
with open(p, "r", encoding="utf-8") as f:
    for line in f:
        d = json.loads(line)
        if d.get("type") == "PLANNER_RESPONSE":
            for tc in d.get("tool_calls", []):
                args = tc.get("args") or tc.get("function", {}).get("arguments") or {}
                if isinstance(args, str):
                    try:
                        args = json.loads(args)
                    except:
                        pass
                if isinstance(args, dict):
                    cmd = args.get("CommandLine", "")
                    if "test" in cmd or "pio" in cmd or "playwright" in cmd:
                        test_calls.append(cmd)

print("Test commands in e5f1d59b-75d1-433d-810a-600350e86169:")
for t in test_calls:
    print("  ", t)

